/* coco_direct.h -- the on-disk layout of a Color Computer OS-9 floppy.**** WRITTEN FOR THE OS-9 COLLECTION.  The header the release shipped said in** its own first line that it was "modified from the OSK version", so it** derived from Microware's <direct.h>, and this collection does not carry** Microware's headers.  What the program actually needs is a description of** what is ON THE MEDIA it reads, which is a disk format rather than a** system interface: a CoCo directory entry gives the name 29 characters and** the descriptor address 3 bytes, where OS-9/68000 uses 28 and a long.**** The member names are the ones os9dsk's own code uses.*//* A directory entry, as it sits on a CoCo disk. */struct dirent {	char	dir_name[29];	/* the name, last character high-bit set */	char	dir_addr[3];	/* LSN of this file's descriptor */};/* A file descriptor sector: what a file is, who owns it, and the runs of** sectors holding it.  A segment list of 48 entries fills the sector.*/struct fildes {	char	fd_att,			/* attributes: d s pe pw pr e w r */		fd_own[2],		/* owner */		fd_date[5],		/* last modified: y m d h m */		fd_link,		/* how many names point here */		fd_fsize[4],		/* size in bytes */		fd_dcr[3];		/* created: y m d */	struct {		char	addr[3],	/* first LSN of the run */			size[2];	/* how many sectors in it */	} fdseg[48];};/* Sector zero: what the disk itself says it is. */struct ddsect {	char	dd_tot[3];	/* sectors on the media */	char	dd_tks;		/* sectors per track */	short	dd_map;		/* bytes in the allocation map */	short	dd_bit;		/* sectors per cluster */	char	dd_dir[3];	/* LSN of the root directory */	char	dd_own[2];	/* disk owner */	char	dd_att;		/* disk attributes */	short	dd_dsk;		/* disk ID */	char	dd_fmt;		/* sides and density */	char	dd_spt[2];	/* sectors per track */	char	dd_res[2];	/* reserved */	char	dd_bt[3];	/* LSN of the bootstrap */	short	dd_bsz;		/* size of the bootstrap */	char	dd_date[5];	/* when the disk was made */	char	dd_name[32];	/* volume name, high-bit terminated */	char	dd_opt[32];	/* path descriptor options */#ifdef OSK	unsigned char	dd_res2;	/* reserved */	unsigned char	dd_sync[4];	/* media integrity code */	unsigned	dd_maplsn;	/* bitmap start LSN, if not zero */	unsigned short	dd_lsnsize;	/* sector size, 0 meaning 256 */#else	char		dd_res2;	char		dd_sync[4];	long		dd_maplsn;	unsigned	dd_lsnsize;#endif	char	dd_null[150];	/* the rest of the sector */};